class Solution {
public:
    int treeDiameter(std::vector<std::vector<int>>& edges) {
        if (edges.empty()) return 0;
        int n = edges.size() + 1;
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        auto bfs = [&](int start) -> std::pair<int, int> {
            std::vector<int> dist(n, -1);
            dist[start] = 0;
            std::queue<int> q;
            q.push(start);
            int furthest = start, maxDist = 0;
            while (!q.empty()) {
                int curr = q.front();
                q.pop();
                int d = dist[curr];
                if (d > maxDist) {
                    maxDist = d;
                    furthest = curr;
                }
                for (int neighbor : adj[curr]) {
                    if (dist[neighbor] == -1) {
                        dist[neighbor] = d + 1;
                        q.push(neighbor);
                    }
                }
            }
            return {furthest, maxDist};
        };

        auto [endpointA, _] = bfs(0);
        auto [_, diameter] = bfs(endpointA);
        return diameter;
    }
};

class Solution {
    public int treeDiameter(int[][] edges) {
        if (edges.length == 0) return 0;
        int n = edges.length + 1;
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new java.util.ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] res1 = bfs(0, adj, n);
        int[] res2 = bfs(res1[0], adj, n);
        return res2[1];
    }

    private int[] bfs(int start, java.util.List<java.util.List<Integer>> adj, int n) {
        int[] dist = new int[n];
        java.util.Arrays.fill(dist, -1);
        dist[start] = 0;
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        q.add(start);
        int furthest = start, maxDist = 0;
        while (!q.isEmpty()) {
            int curr = q.poll();
            int d = dist[curr];
            if (d > maxDist) {
                maxDist = d;
                furthest = curr;
            }
            for (int neighbor : adj.get(curr)) {
                if (dist[neighbor] == -1) {
                    dist[neighbor] = d + 1;
                    q.add(neighbor);
                }
            }
        }
        return new int[]{furthest, maxDist};
    }
}

var treeDiameter = function(edges) {
    if (edges.length === 0) return 0;
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const bfs = (start) => {
        const dist = new Array(n).fill(-1);
        dist[start] = 0;
        const q = [start];
        let furthest = start, maxDist = 0;
        while (q.length > 0) {
            const curr = q.shift();
            const d = dist[curr];
            if (d > maxDist) {
                maxDist = d;
                furthest = curr;
            }
            for (const neighbor of adj[curr]) {
                if (dist[neighbor] === -1) {
                    dist[neighbor] = d + 1;
                    q.push(neighbor);
                }
            }
        }
        return [furthest, maxDist];
    };

    const [endpointA] = bfs(0);
    const [, diameter] = bfs(endpointA);
    return diameter;
};
